import sys, json, time, random
sys.path.insert(0,'/workspace/dev'); sys.path.insert(0,'/workspace/submission')
import harness; harness.setup_env()
import formats, pipeline, resource

PAD = 1514
LEAD = [1100, 1200, 1300]
TAIL = [1400, 1420, 1450, 1480]


def safe(rng, low=1000, high=2000):
    v = rng.randint(low, high)
    return 1513 if v == PAD else v


def drow(seq, cls):
    return {'class': cls, 'values': LEAD + list(seq) + TAIL,
            'activation': [0] * len(LEAD) + [1000] * len(seq) + [0] * len(TAIL)}


def build():
    rng = random.Random(101)
    releases = []
    discovery_rows = 4096
    validation_rows = 6000
    per_release = discovery_rows // 8
    templates = {}
    for index in range(per_release * 8 // 2):
        templates[index] = [safe(rng, 1600, 2600) for _ in range(4)]
    for r_index in range(8):
        rows = []
        for k in range(per_release):
            seq = templates[(r_index * per_release + k) % len(templates)]
            rows.append(drow(seq, k % 4))
        train = [{'class': c, 'values': templates[c] } for c in range(4)]
        for _ in range(300):
            train.append({'class': rng.randrange(4),
                          'values': [safe(rng) for _ in range(rng.randint(2, 8))]})
        validation = []
        for _ in range(validation_rows // 8):
            validation.append({'class': rng.randrange(4),
                               'values': [safe(rng) for _ in range(128)]})
        for c in range(4):
            validation.append({'class': c, 'values': templates[c]})
        releases.append({'id': 'm%d' % r_index, 'classes': 4, 'width': 4,
                         'eps': [30, 1], 'ratio': [1, 8], 'threshold': [0, 1],
                         'mode': 'range' if r_index % 2 else 'exact',
                         'packet_limit': 200000, 'idle_us': 10 ** 12,
                         'discovery': rows, 'train': train, 'validation': validation})
    ops = []
    flows = 8192
    ops.append(['install', 'm0'])
    for f in range(flows):
        name = 'f%04d' % f
        ops.append(['open', name])
        for position in range(200000 // flows):
            ops.append(['packet', name, position, position % 2,
                        rng.choice([86, 87, 100, 148, 200, 300])])
        ops.append(['close', name])
    for f in range(flows):
        ops.append(['open', 'f%04d' % f])
    for f in range(flows):
        ops.append(['close', 'f%04d' % f])
    for i in range(2048 - 1):
        ops.append(['install', 'm%d' % (i % 8)])
    return {'capacity': {'range': 4096, 'exact': 8192}, 'releases': releases,
            'blocks': [ops]}


if __name__ == '__main__':
    request = build()
    text = json.dumps(request, separators=(',', ':'))
    print('bytes', len(text), 'ops', sum(len(b) for b in request['blocks']))
    start = time.time()
    out = pipeline.execute(formats.validate(json.loads(text)))
    print('elapsed %.1fs' % (time.time() - start))
    print('rss MB', resource.getrusage(resource.RUSAGE_SELF).ru_maxrss / 1024)
    for cat in out['catalog']:
        print(cat['id'], 'frags', len(cat['fragments']), 'clusters', len(cat['clusters']),
              'kept', len(cat['priority']), 'noise', len(cat['noise']), 'entries', cat['entries'])
    print('decisions', len(out['decisions']), 'installs', len(out['installs']))
    reasons = {}
    for d in out['decisions']:
        reasons[d['reason']] = reasons.get(d['reason'], 0) + 1
    print(reasons)
    print('final', out['final'])
